create table if not exists app.journal_entries (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists app.journal_versions (id uuid primary key default gen_random_uuid(), entry_id uuid not null references app.journal_entries(id) on delete cascade, version integer not null, text text not null, content_hash text not null, created_at timestamptz not null default now(), unique (entry_id, version));
create table if not exists app.journal_tags (entry_id uuid not null references app.journal_entries(id) on delete cascade, tag text not null, primary key (entry_id, tag));
create table if not exists app.journal_insights (id uuid primary key default gen_random_uuid(), entry_id uuid not null references app.journal_entries(id) on delete cascade, text text not null, source_version_hash text not null, status text not null default 'candidate', created_at timestamptz not null default now());
create table if not exists app.interview_processes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, application_id uuid not null references app.applications(id) on delete cascade, confidence text not null default 'low', created_at timestamptz not null default now());
create table if not exists app.interview_stages (id uuid primary key default gen_random_uuid(), process_id uuid not null references app.interview_processes(id) on delete cascade, name text not null, display_order integer not null, status text not null default 'proposed', source text not null default 'unknown', scheduled_at timestamptz, completed_at timestamptz);
create table if not exists app.interview_stage_history (id uuid primary key default gen_random_uuid(), stage_id uuid not null references app.interview_stages(id) on delete cascade, from_status text, to_status text not null, reason text, created_at timestamptz not null default now());
create table if not exists app.preparation_kits (id uuid primary key default gen_random_uuid(), stage_id uuid not null references app.interview_stages(id) on delete cascade, schema_version text not null, payload jsonb not null, created_at timestamptz not null default now());
create table if not exists app.star_stories (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, title text not null, situation text not null, task text not null, action text not null, result text not null, evidence_ids uuid[] not null default '{}');
create table if not exists app.mock_interviews (id uuid primary key default gen_random_uuid(), stage_id uuid not null references app.interview_stages(id) on delete cascade, status text not null default 'draft', notes text, feedback jsonb, created_at timestamptz not null default now());
alter table app.journal_entries enable row level security; alter table app.interview_processes enable row level security; alter table app.star_stories enable row level security;
create policy journal_owner on app.journal_entries for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy interview_process_owner on app.interview_processes for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy star_stories_owner on app.star_stories for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
